CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, telegram_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('WORKER','CHIEF')), admin INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, position INTEGER NOT NULL, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), due_date TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS document_period ON documents(deleted,due_date,category_id);
CREATE TABLE IF NOT EXISTS audit_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, document_id TEXT, actor_id TEXT NOT NULL REFERENCES users(id), actor_name TEXT NOT NULL, type TEXT NOT NULL, at TEXT NOT NULL, batch_id TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_document ON audit_events(document_id,seq);
CREATE TABLE IF NOT EXISTS schedule_versions (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, effective_start TEXT NOT NULL, anchor TEXT NOT NULL, interval INTEGER NOT NULL CHECK(interval>0), actor_id TEXT, at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_periods (id TEXT PRIMARY KEY, start TEXT NOT NULL, end TEXT NOT NULL, schedule_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_records (id TEXT PRIMARY KEY, period_id TEXT NOT NULL REFERENCES review_periods(id), actor_id TEXT NOT NULL REFERENCES users(id), actor_name TEXT NOT NULL, at TEXT NOT NULL, snapshot TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS batch_operations (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_keys (actor_id TEXT NOT NULL, key TEXT NOT NULL, fingerprint TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
PRAGMA user_version=1;
